        raise exception_class(*args, **kwargs)
    except Exception:
        # Capture the traceback output
        import io
        import contextlib
        f = io.StringIO()
        with contextlib.redirect_stdout(f):
            Traceback.from_exception(
                type_(exception_class),
                value_(exception_class(*args, **kwargs)),
                None, # No actual traceback object for this simple test
                width=80,
                code_width=80,
                extra_lines=0,
                show_locals=False,
            )
        output = f.getvalue()
